import urllib.request
import urllib.error
import time

class RateLimitError(Exception):
    pass

class ServerError(Exception):
    pass

class ClientError(Exception):
    pass

class ConnectionError(Exception):
    pass

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url.rstrip('/')
        self.timeout = timeout

    def get(self, path):
        url = f"{self.base_url}{path}"

        # Retry configurations
        rate_limit_retries = 0
        server_retries = 0
        network_retries = 0

        backoff_schedule = [0.5, 1, 2]

        while True:
            try:
                with urllib.request.urlopen(url, timeout=self.timeout) as response:
                    return response.read().decode('utf-8')

            except urllib.error.HTTPError as e:
                status = e.code

                if status == 429:
                    if rate_limit_retries < 3:
                        time.sleep(backoff_schedule[rate_limit_retries])
                        rate_limit_retries += 1
                        continue
                    raise RateLimitError(f"Rate limit exceeded after 3 retries: {e}")

                elif 500 <= status < 600:
                    if server_retries < 1:
                        time.sleep(1)
                        server_retries += 1
                        continue
                    raise ServerError(f"Server error after retry: {e}")

                elif 400 <= status < 500:
                    raise ClientError(f"Client error occurred: {e}")

                raise e

            except urllib.error.URLError as e:
                if network_retries < 1:
                    time.sleep(1)
                    network_retries += 1
                    continue
                raise ConnectionError(f"Network connection failed after retry: {e}")
